#include <print>

void by_value(int x) { x = 999; std::println("函数里拿到: {}", x); }

void swap_two(int& a, int& b) {
    int t = a;
    a = b;
    b = t;
}

int main() {
    int a = 10;
    by_value(a);
    std::println("传值后 a = {}", a);

    int x = 1, y = 7;
    swap_two(x, y);
    std::println("x = {} y = {}", x, y);
    return 0;
}

